<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/reviews.php';
reviews_start_session();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Отзывы — АртСитиСтрой</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f6;color:#17232c;font:15px Arial,sans-serif}.wrap{width:min(980px,calc(100% - 28px));margin:35px auto}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:24px}.brand{font-size:23px;font-weight:900}.brand span{color:#ed6b25}.panel{background:#fff;border:1px solid #e1e6e8;border-radius:14px;padding:24px;margin-bottom:18px;box-shadow:0 8px 24px #17232c0a}h1{font-size:27px;margin:0 0 8px}h2{font-size:20px;margin:0 0 17px}.muted{color:#68757d}.field{display:grid;gap:7px;margin:14px 0}.field input,.field textarea{width:100%;padding:12px;border:1px solid #ccd4d8;border-radius:8px;font:inherit}.field textarea{min-height:130px;resize:vertical}button,.btn{border:0;border-radius:8px;padding:11px 16px;background:#ed6b25;color:white;font-weight:700;cursor:pointer}.secondary{background:#263640}.danger{background:#a93226}.hidden{display:none!important}.msg{margin-top:12px;color:#a93226}.review{border-top:1px solid #e6eaec;padding:18px 0}.photos{display:flex;gap:10px;flex-wrap:nowrap;overflow-x:auto;overflow-y:hidden;padding:4px 2px 10px;margin:12px 0;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch}.photo{position:relative;flex:0 0 auto;scroll-snap-align:start}.photo img{width:112px;height:92px;object-fit:cover;border-radius:8px;border:1px solid #ddd}.photo button{position:absolute;right:-5px;top:-7px;padding:4px 7px;background:#a93226}.actions{display:flex;gap:8px;flex-wrap:wrap}.review-text{white-space:pre-wrap;margin:10px 0}.hint{font-size:13px;color:#68757d}@media(max-width:600px){.panel{padding:17px}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="wrap">
<div class="top"><div class="brand">Арт<span>Сити</span>Строй · Отзывы</div><div><a href="/admin/content.php" class="muted">Редактор сайта</a>　<a href="/" class="muted">← На сайт</a></div></div>
<section class="panel" id="login"><h1>Вход в админ-панель</h1><p class="muted">Войдите, чтобы управлять отзывами клиентов.</p><form id="loginForm"><label class="field">Электронная почта<input name="email" type="email" autocomplete="username" required value="sergejacenko765@gmail.com"></label><label class="field">Пароль<input name="password" type="password" autocomplete="current-password" required></label><button type="submit">Войти</button><div class="msg" id="loginMsg" role="status"></div></form></section>
<section id="dashboard" class="hidden"><div class="panel"><div class="top"><div><h1>Управление отзывами</h1><div class="muted">Текст отзыва можно изменить: нажмите «Редактировать текст и фото», поправьте текст и сохраните. Фотографии пролистываются горизонтально.</div></div><button class="secondary" id="logout">Выйти</button></div>
<form id="reviewForm"><input type="hidden" name="id"><label class="field">Текст отзыва (необязательно)<textarea name="text" maxlength="5000" placeholder="Можно оставить пустым, если добавляете фотографии"></textarea><span class="hint">Можно опубликовать отзыв только с фотографиями, без текста.</span></label><label class="field">Фотографии (JPG, PNG или WebP)<input type="file" name="photos[]" accept="image/jpeg,image/png,image/webp" multiple><span class="hint">До 10 файлов за загрузку, до 8 МБ каждый. При редактировании можно добавить ещё фото.</span></label><div class="actions"><button type="submit" id="saveBtn">Добавить отзыв</button><button type="button" class="secondary hidden" id="cancelEdit">Отмена</button></div><div class="msg" id="formMsg" role="status"></div></form></div>
<div class="panel"><h2>Опубликованные отзывы</h2><div id="reviewList" class="muted">Загрузка…</div></div></section></main>
<script>
let csrf=null,reviews=[];const $=s=>document.querySelector(s);
async function request(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Ошибка запроса');return d}
function showAdmin(){$('#login').classList.add('hidden');$('#dashboard').classList.remove('hidden');loadReviews()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadReviews(){try{reviews=(await request('/api/reviews.php')).reviews;render()}catch(e){$('#reviewList').textContent=e.message}}
function render(){if(!reviews.length){$('#reviewList').textContent='Пока отзывов нет. Добавьте первый отзыв выше.';return}
$('#reviewList').innerHTML=reviews.map(r=>'<article class="review"><div class="review-text">'+esc(r.text)+'</div><div class="photos">'+(r.photos||[]).map(p=>'<div class="photo"><a href="'+esc(p)+'" target="_blank" rel="noopener"><img src="'+esc(p)+'" alt="Фото отзыва"></a><button type="button" data-photo="'+esc(p)+'" data-id="'+esc(r.id)+'" title="Удалить фото">×</button></div>').join('')+'</div><div class="actions"><button type="button" class="secondary" data-edit="'+esc(r.id)+'">Редактировать текст и фото</button><button type="button" class="danger" data-delete="'+esc(r.id)+'">Удалить отзыв</button></div></article>').join('')}
function resetForm(){$('#reviewForm').reset();$('#reviewForm [name=id]').value='';$('#saveBtn').textContent='Добавить отзыв';$('#cancelEdit').classList.add('hidden');$('#formMsg').textContent=''}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginMsg').textContent='';try{const d=await request('/admin/api.php?action=login',{method:'POST',body:new FormData(e.currentTarget)});csrf=d.csrf;showAdmin()}catch(err){$('#loginMsg').textContent=err.message}});
$('#reviewForm').addEventListener('submit',async e=>{e.preventDefault();$('#formMsg').textContent='Сохраняю…';const fd=new FormData(e.currentTarget);fd.append('csrf',csrf);try{await request('/admin/api.php?action=save',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});resetForm();await loadReviews();$('#formMsg').textContent='Отзыв сохранён.'}catch(err){$('#formMsg').textContent=err.message}});
$('#reviewList').addEventListener('click',async e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]'),photo=e.target.closest('[data-photo]');
if(edit){const r=reviews.find(x=>x.id===edit.dataset.edit);if(!r)return;$('#reviewForm [name=id]').value=r.id;$('#reviewForm [name=text]').value=r.text;$('#saveBtn').textContent='Сохранить изменения';$('#cancelEdit').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'});$('#reviewForm [name=text]').focus({preventScroll:true});return}
if(del&&confirm('Удалить отзыв вместе со всеми фотографиями?')){try{const fd=new FormData();fd.append('id',del.dataset.delete);fd.append('csrf',csrf);await request('/admin/api.php?action=delete',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});await loadReviews()}catch(err){alert(err.message)}}
if(photo&&confirm('Удалить эту фотографию?')){try{const fd=new FormData();fd.append('id',photo.dataset.id);fd.append('photo',photo.dataset.photo);fd.append('csrf',csrf);await request('/admin/api.php?action=delete_photo',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});await loadReviews()}catch(err){alert(err.message)}}});
$('#cancelEdit').addEventListener('click',resetForm);
$('#logout').addEventListener('click',async()=>{try{const fd=new FormData();fd.append('csrf',csrf);await request('/admin/api.php?action=logout',{method:'POST',headers:{'X-CSRF-Token':csrf},body:fd});location.reload()}catch(e){alert(e.message)}});
(async()=>{try{const d=await request('/admin/api.php?action=status');if(d.authenticated){csrf=d.csrf;showAdmin()}else if(!d.configured)$('#loginMsg').textContent='Администратор ещё не настроен. Выполните команду настройки на сервере.'}catch(e){$('#loginMsg').textContent=e.message}})();
</script></body></html>